local _, addon = ...
-- Fully qualified addon table paths stay editable in RPTextStudio.
addon.localeData.deDE.generalTexts.INCOMING = { gruppe = { "Achtung! Besuch, und nicht von der freundlichen Sorte!", "Die Gegner kommen näher. Macht Euch bereit." }, ziel = { "%s: Die Gegner kommen näher. Macht Euch bereit.", "%s: Achtung! Besuch, und nicht von der freundlichen Sorte!" } }
addon.localeData.deDE.generalTexts.INSULT = { gruppe = { "Manche Worte verdienen keine höfliche Antwort.", "Eure Arroganz ist größer als Eure Weisheit." }, ziel = { "%s: Eure Arroganz ist größer als Eure Weisheit.", "%s: Manche Worte verdienen keine höfliche Antwort." } }
addon.localeData.deDE.generalTexts.INTRODUCE = { gruppe = { "Gestattet, dass ich mich vorstelle.", "Ein guter Anfang beginnt mit einem Namen." }, ziel = { "%s: Ein guter Anfang beginnt mit einem Namen.", "%s: Gestattet, dass ich mich vorstelle." } }
addon.localeData.deDE.generalTexts.JK = { gruppe = { "Nur ein Scherz! Legt die Waffen wieder weg.", "Ein bisschen Humor darf gefährlich aussehen." }, ziel = { "%s: Ein bisschen Humor darf gefährlich aussehen.", "%s: Nur ein Scherz! Legt die Waffen wieder weg." } }
addon.localeData.deDE.generalTexts.KISS = { gruppe = { "Ein Kuss sagt bisweilen mehr als viele Reden.", "Das Leben ist zu kurz für vergessene Zuneigung." }, ziel = { "%s: Das Leben ist zu kurz für vergessene Zuneigung.", "%s: Ein Kuss sagt bisweilen mehr als viele Reden." } }
addon.localeData.deDE.generalTexts.KNUCKLES = { gruppe = { "Die Hände sind bereit. Wie steht es mit Euch?", "Das wird ein ehrlicher Kampf, hoffe ich." }, ziel = { "%s: Das wird ein ehrlicher Kampf, hoffe ich.", "%s: Die Hände sind bereit. Wie steht es mit Euch?" } }
addon.localeData.deDE.generalTexts.LAVISH = { gruppe = { "An Komplimenten sollte man nicht sparen.", "Euer Auftritt verdient eine königliche Würdigung." }, ziel = { "%s: Euer Auftritt verdient eine königliche Würdigung.", "%s: An Komplimenten sollte man nicht sparen." } }
addon.localeData.deDE.generalTexts.LICK = { gruppe = { "Der Geschmack ist... ungewöhnlich.", "Vielleicht hätte ich vorher fragen sollen." }, ziel = { "%s: Vielleicht hätte ich vorher fragen sollen.", "%s: Der Geschmack ist... ungewöhnlich." } }
addon.localeData.deDE.generalTexts.LISTEN = { gruppe = { "Einen Augenblick. Ich höre etwas.", "Die leisen Stimmen erzählen oft mehr." }, ziel = { "%s: Die leisen Stimmen erzählen oft mehr.", "%s: Einen Augenblick. Ich höre etwas." } }
addon.localeData.deDE.generalTexts.LOST = { gruppe = { "Diese Abzweigung stand nicht auf meiner Karte.", "Wir sind nicht verloren, nur unerwartet unterwegs." }, ziel = { "%s: Wir sind nicht verloren, nur unerwartet unterwegs.", "%s: Diese Abzweigung stand nicht auf meiner Karte." } }
addon.localeData.deDE.generalTexts.MASSAGE = { gruppe = { "Ein langer Marsch verlangt seinen Preis.", "Die Schultern brauchen dringend Erholung." }, ziel = { "%s: Die Schultern brauchen dringend Erholung.", "%s: Ein langer Marsch verlangt seinen Preis." } }
addon.localeData.deDE.generalTexts.MOAN = { gruppe = { "Das war unangenehmer, als ich gehofft hatte.", "Man darf auch einmal klagen, oder?" }, ziel = { "%s: Man darf auch einmal klagen, oder?", "%s: Das war unangenehmer, als ich gehofft hatte." } }
addon.localeData.deDE.generalTexts.MOCK = { gruppe = { "Wirklich beeindruckend. Beinahe.", "Vielleicht übt Ihr das noch ein wenig." }, ziel = { "%s: Vielleicht übt Ihr das noch ein wenig.", "%s: Wirklich beeindruckend. Beinahe." } }
addon.localeData.deDE.generalTexts.MOON = { gruppe = { "Das wird mancher heute nicht so schnell vergessen.", "Ich nenne es einen ungewöhnlichen Gruß." }, ziel = { "%s: Ich nenne es einen ungewöhnlichen Gruß.", "%s: Das wird mancher heute nicht so schnell vergessen." } }
addon.localeData.deDE.generalTexts.MOURN = { gruppe = { "Ein Leben ist mehr als seine letzte Stunde.", "Möge die Erinnerung länger bleiben als der Schmerz." }, ziel = { "%s: Möge die Erinnerung länger bleiben als der Schmerz.", "%s: Ein Leben ist mehr als seine letzte Stunde." } }
addon.localeData.deDE.generalTexts.NO = { gruppe = { "Nein. Und dabei bleibt es.", "Nicht jeder Vorschlag verdient Zustimmung." }, ziel = { "%s: Nicht jeder Vorschlag verdient Zustimmung.", "%s: Nein. Und dabei bleibt es." } }
addon.localeData.deDE.generalTexts.NOSEPICK = { gruppe = { "Manche Untersuchungen sind besser privat.", "Das war jetzt nicht besonders vornehm." }, ziel = { "%s: Das war jetzt nicht besonders vornehm.", "%s: Manche Untersuchungen sind besser privat." } }
addon.localeData.deDE.generalTexts.OOM = { gruppe = { "Meine magischen Reserven sind vollständig erschöpft!", "Ein Schluck Wasser wird das allein nicht richten." }, ziel = { "%s: Ein Schluck Wasser wird das allein nicht richten.", "%s: Meine magischen Reserven sind vollständig erschöpft!" } }
addon.localeData.deDE.generalTexts.OPENFIRE = { gruppe = { "Auf mein Zeichen! Jetzt Feuer frei!", "Ziel erfassen und die Linie halten." }, ziel = { "%s: Ziel erfassen und die Linie halten.", "%s: Auf mein Zeichen! Jetzt Feuer frei!" } }
addon.localeData.deDE.generalTexts.PANIC = { gruppe = { "Das war nicht Teil des Plans!", "Warum rennt denn plötzlich alles durcheinander?" }, ziel = { "%s: Warum rennt denn plötzlich alles durcheinander?", "%s: Das war nicht Teil des Plans!" } }
addon.localeData.deDE.generalTexts.PARTY = { gruppe = { "Heute bleibt das Abenteuer vor der Tür.", "Musik und Freunde sind Grund genug zum Feiern." }, ziel = { "%s: Musik und Freunde sind Grund genug zum Feiern.", "%s: Heute bleibt das Abenteuer vor der Tür." } }
addon.localeData.deDE.generalTexts.PAT = { gruppe = { "Gut gemacht. Das war nicht leicht.", "Manchmal verdient Mut einfach Anerkennung." }, ziel = { "%s: Manchmal verdient Mut einfach Anerkennung.", "%s: Gut gemacht. Das war nicht leicht." } }
addon.localeData.deDE.generalTexts.PEER = { gruppe = { "Dort hinten bewegt sich doch etwas.", "Ich werde genauer hinschauen, bevor ich urteile." }, ziel = { "%s: Ich werde genauer hinschauen, bevor ich urteile.", "%s: Dort hinten bewegt sich doch etwas." } }
addon.localeData.deDE.generalTexts.PEST = { gruppe = { "Ein wenig Unruhe hält die Gesellschaft wach.", "Vielleicht sollte ich jemanden weniger ärgern." }, ziel = { "%s: Vielleicht sollte ich jemanden weniger ärgern.", "%s: Ein wenig Unruhe hält die Gesellschaft wach." } }
addon.localeData.deDE.generalTexts.PICK = { gruppe = { "Manche Dinge lassen sich mit Geduld lösen.", "Ein kluger Griff spart viel Mühe." }, ziel = { "%s: Ein kluger Griff spart viel Mühe.", "%s: Manche Dinge lassen sich mit Geduld lösen." } }
addon.localeData.deDE.generalTexts.PITY = { gruppe = { "Das hätte niemand erleben sollen.", "Mein Mitgefühl gilt allen Betroffenen." }, ziel = { "%s: Mein Mitgefühl gilt allen Betroffenen.", "%s: Das hätte niemand erleben sollen." } }
addon.localeData.deDE.generalTexts.PIZZA = { gruppe = { "Eine warme Mahlzeit rettet so manchen Abend.", "Wer ein Stück abhaben will, meldet sich jetzt." }, ziel = { "%s: Wer ein Stück abhaben will, meldet sich jetzt.", "%s: Eine warme Mahlzeit rettet so manchen Abend." } }
addon.localeData.deDE.generalTexts.PLEAD = { gruppe = { "Ich bitte Euch, hört mich zu Ende an.", "Es steht mehr auf dem Spiel, als Ihr glaubt." }, ziel = { "%s: Es steht mehr auf dem Spiel, als Ihr glaubt.", "%s: Ich bitte Euch, hört mich zu Ende an." } }
addon.localeData.deDE.generalTexts.POKE = { gruppe = { "Seid Ihr noch unter den Lebenden?", "Ein kleiner Hinweis sollte wohl genügen." }, ziel = { "%s: Ein kleiner Hinweis sollte wohl genügen.", "%s: Seid Ihr noch unter den Lebenden?" } }
addon.localeData.deDE.generalTexts.PONDER = { gruppe = { "Das verdient einen gründlichen Gedanken.", "Nicht jede Antwort mag sofort gefunden werden." }, ziel = { "%s: Nicht jede Antwort mag sofort gefunden werden.", "%s: Das verdient einen gründlichen Gedanken." } }
addon.localeData.deDE.generalTexts.POUNCE = { gruppe = { "Überraschung! Jetzt seid Ihr dran.", "Der beste Plan beginnt oft mit einem Sprung." }, ziel = { "%s: Der beste Plan beginnt oft mit einem Sprung.", "%s: Überraschung! Jetzt seid Ihr dran." } }
addon.localeData.deDE.generalTexts.PRAISE = { gruppe = { "Das verdient aufrichtige Anerkennung.", "Große Taten brauchen keine großen Worte." }, ziel = { "%s: Große Taten brauchen keine großen Worte.", "%s: Das verdient aufrichtige Anerkennung." } }
addon.localeData.deDE.generalTexts.PRAY = { gruppe = { "Möge uns heute ein wenig Weisheit begleiten.", "Auch im Sturm gibt es Platz für Hoffnung." }, ziel = { "%s: Auch im Sturm gibt es Platz für Hoffnung.", "%s: Möge uns heute ein wenig Weisheit begleiten." } }
addon.localeData.deDE.generalTexts.PUZZLED = { gruppe = { "Mir fehlt noch ein Stück des Rätsels.", "Die Antwort liegt wahrscheinlich direkt vor uns." }, ziel = { "%s: Die Antwort liegt wahrscheinlich direkt vor uns.", "%s: Mir fehlt noch ein Stück des Rätsels." } }
addon.localeData.deDE.generalTexts.QUESTION = { gruppe = { "Darf ich dazu etwas fragen?", "Wer nachfragt, hat oft schon halb verstanden." }, ziel = { "%s: Wer nachfragt, hat oft schon halb verstanden.", "%s: Darf ich dazu etwas fragen?" } }
